  const heap = new Heap((a, b) => a.val - b.val);   // the current head of each list
  for (const head of lists) if (head) heap.push(head);
  const dummy = new ListNode(0);
  let tail = dummy;
  while (heap.size() > 0) {
    const node = heap.pop();                // the smallest head of all
    tail.next = node;
    tail = node;
    if (node.next) heap.push(node.next);    // its list moves forward
  }
  return dummy.next;
}

ListNode mergeKLists(ListNode[] lists) {
    PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));   // current heads
    for (ListNode head : lists) if (head != null) heap.offer(head);
    ListNode dummy = new ListNode(0), tail = dummy;
    while (!heap.isEmpty()) {
        ListNode node = heap.poll();         // the smallest head of all
        tail.next = node;
        tail = node;
        if (node.next != null) heap.offer(node.next);   // its list moves forward
    }
    return dummy.next;
}

ListNode* mergeKLists(vector<ListNode*>& lists) {
    auto later = [](ListNode* a, ListNode* b) { return a->val > b->val; };   // a min-heap by value
    priority_queue<ListNode*, vector<ListNode*>, decltype(later)> heap(later);
    for (ListNode* head : lists) if (head) heap.push(head);
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (!heap.empty()) {
        ListNode* node = heap.top();         // the smallest head of all
        heap.pop();
        tail->next = node;
        tail = node;
        if (node->next) heap.push(node->next);   // its list moves forward
    }
    return dummy.next;
}
